]
\node {Study}
  child { node {Pass} edge from parent node[left,draw=none,fill=none,font=\scriptsize] {Yes} }
  child { node {Sleep}
    child { node {Fail} edge from parent node[left,draw=none,fill=none,font=\scriptsize] {Enough} }
    child { node {Pass} edge from parent node[right,draw=none,fill=none,font=\scriptsize] {Little} }
    edge from parent node[right,draw=none,fill=none,font=\scriptsize] {No} };
\end{tikzpicture}
\end{center}
\boxed{\text{Final Tree: Study} \to \{\text{Yes}: \text{Pass}, \ \text{No} \to \text{Sleep} \to \{\text{Enough}: \text{Fail}, \text{Little}: \text{Pass}\}\}}

Given:
\begin{itemize}[leftmargin=2em]
\item $P(\text{Disease}) = 0.01$
\item $P(\text{Positive} \mid \text{Disease}) = 0.9$
\item $P(\text{Positive} \mid \text{NoDisease}) = 0.05$
\end{itemize}
Find $P(\text{Disease} \mid \text{Positive})$.

\textbf{Solution:}
\begin{align*}
P(\text{Positive}) &= P(\text{Positive}|\text{Disease})P(\text{Disease}) + P(\text{Positive}|\text{NoDisease})P(\text{NoDisease}) \\
&= (0.9)(0.01) + (0.05)(0.99) \\
&= 0.009 + 0.0495 = 0.0585 \\[4pt]
P(\text{Disease}|\text{Positive}) &= \frac{0.009}{0.0585}
\end{align*}
\boxed{P(\text{Disease}\mid\text{Positive}) \approx 0.154}

Bag A has 3 red and 2 blue balls. Bag B has 1 red and 4 blue balls. A bag is chosen at random (equal probability) and a red ball is drawn. Find $P(\text{Bag A} \mid \text{Red})$.

\textbf{Solution:}
\begin{align*}
P(A) = P(B) &= 0.5 \\
P(\text{Red}|A) &= \frac{3}{5} = 0.6, \qquad P(\text{Red}|B) = \frac{1}{5} = 0.2 \\
P(\text{Red}) &= (0.6)(0.5) + (0.2)(0.5) = 0.3 + 0.1 = 0.4 \\[4pt]
P(A|\text{Red}) &= \frac{0.3}{0.4}
\end{align*}
\boxed{P(\text{Bag A}\mid\text{Red}) = 0.75}

Given:
\begin{itemize}[leftmargin=2em]
\item $P(\text{Rain}) = 0.3$
\item $P(\text{Cloudy} \mid \text{Rain}) = 0.8$
\item $P(\text{Cloudy} \mid \text{NoRain}) = 0.4$
\end{itemize}
Find $P(\text{Rain} \mid \text{Cloudy})$.

\textbf{Solution:}
\begin{align*}
P(\text{Cloudy}) &= (0.8)(0.3) + (0.4)(0.7) = 0.24 + 0.28 = 0.52 \\[4pt]
P(\text{Rain}|\text{Cloudy}) &= \frac{0.24}{0.52}
\end{align*}
\boxed{P(\text{Rain}\mid\text{Cloudy}) \approx 0.462}

\subsection{The Naive Bayes Assumption}

Given the class label $C$, the naive Bayes classifier assumes that all attributes $A_1, A_2, \ldots, A_n$ are conditionally independent of one another:
\[
P(A_1, A_2, \ldots, A_n \mid C) = \prod_{i=1}^{n} P(A_i \mid C)
\]
This means that once the class is known, each attribute's probability can be computed on its own, without needing to know the values of the other attributes.

The diagram below shows this assumption as a simple graphical model: the class $C$ independently influences each attribute, and there are no direct connections between attributes themselves.

\begin{center}
\begin{tikzpicture}[
  every node/.style={circle,draw=primaryblue,thick,fill=primaryblue!8,minimum size=1.1cm,font=\small},
  every path/.style={draw,thick,-{Stealth[length=2.5mm]}}
]
\node (C) at (0,2.2) {$C$};
\node (A1) at (-2.6,0) {$A_1$};
\node (A2) at (0,0) {$A_2$};
\node (A3) at (2.6,0) {$A_3$};
\draw (C) -- (A1);
\draw (C) -- (A2);
\draw (C) -- (A3);
\end{tikzpicture}
\end{center}

This is the same "product of independent probabilities" idea used when multiplying probabilities of independent events.

\subsection{Naive Bayes Classification}

\begin{enumerate}[leftmargin=2em,itemsep=4pt]
\item Compute a score $P(C_k)\prod_{i} P(A_i \mid C_k)$ for every class $C_k$ \hfill\textit{(posterior score)}
\item Predict the class with the \textbf{maximum} score \hfill\textit{(MAP decision rule)}
\item $P(E)$ is the same for every class comparison, so it can be dropped \hfill\textit{(normalization not needed)}
\end{enumerate}
\[
\hat{C} = \arg\max_{C_k} \; P(C_k)\prod_{i=1}^{n} P(A_i \mid C_k)
\]

\begin{center}
\begin{tabular}{ccc}
\toprule
Weather & Wind & PlayCricket \\
\midrule
Sunny & Weak & Yes \\
Sunny & Strong & No \\
Rainy & Weak & Yes \\
Rainy & Strong & Yes \\
Sunny & Weak & Yes \\
Rainy & Strong & No \\
\bottomrule
\end{tabular}
\end{center}
Classify a new instance: Weather = Sunny Wind = Strong.

\textbf{Solution:}
\begin{align*}
P(\text{Yes}) &= \frac{4}{6} = \frac{2}{3}, \qquad P(\text{No}) = \frac{2}{6} = \frac{1}{3} \\[4pt]
P(\text{Sunny}|\text{Yes}) &= \frac{2}{4} = 0.5, \qquad P(\text{Strong}|\text{Yes}) = \frac{1}{4} = 0.25 \\
P(\text{Sunny}|\text{No}) &= \frac{1}{2} = 0.5, \qquad P(\text{Strong}|\text{No}) = \frac{2}{2} = 1
\end{align*}
\begin{align*}
\text{Score}(\text{Yes}) &= \frac{2}{3}(0.5)(0.25) \approx 0.0833 \\
\text{Score}(\text{No}) &= \frac{1}{3}(0.5)(1) \approx 0.1667
\end{align*}
Since $\text{Score}(\text{No}) > \text{Score}(\text{Yes})$:
\boxed{\text{Predicted class: No}}

