\node[input] (b) at (0,-2) {$1$};
\node[sum] (s) at (3,1) {$\sum$};
\node[act] (f) at (5.7,1) {$f$};
\node (y) at (7.6,1) {$y$};
\draw[->,thick] (x1) -- node[above,sloped]{\scriptsize $w_1$} (s);
\draw[->,thick] (x2) -- node[above,sloped]{\scriptsize $w_2$} (s);
\draw[->,thick] (b) -- node[below,sloped]{\scriptsize $b$} (s);
\draw[->,thick] (s) -- node[above]{\scriptsize net} (f);
