\subsection{The SVM Decision Function}

\begin{enumerate}[leftmargin=2em,itemsep=4pt]
\item A point is classified using $f(x) = \text{sign}(w \cdot x + b)$ \hfill\textit{(decision rule)}
\item $w \cdot x + b > 0$ places the point on the $+1$ side \hfill\textit{(positive class)}
\item $w \cdot x + b < 0$ places the point on the $-1$ side \hfill\textit{(negative class)}
\item $w \cdot x + b = 0$ means the point lies exactly on the hyperplane \hfill\textit{(boundary case)}
\end{enumerate}

A trained SVM has $w = (2,-1)$ and $b = -1$. Classify the point $x = (3,1)$.

\textbf{Solution:}
\begin{align*}
\text{score} &= w \cdot x + b = (2)(3) + (-1)(1) + (-1) \\
&= 6 - 1 - 1 = 4
\end{align*}
Since $4 > 0$:
\boxed{\text{Predicted class: } +1}

Using the same SVM as Example 2.28 ($w=(2,-1)$, $b=-1$), classify the point $x = (0,3)$.

\textbf{Solution:}
\begin{align*}
\text{score} &= (2)(0) + (-1)(3) + (-1) \\
&= 0 - 3 - 1 = -4
\end{align*}
Since $-4 < 0$:
\boxed{\text{Predicted class: } -1}

Using the same SVM as Example 2.28 ($w=(2,-1)$, $b=-1$), classify the point $x = (1,1)$.

\textbf{Solution:}
\begin{align*}
\text{score} &= (2)(1) + (-1)(1) + (-1) \\
&= 2 - 1 - 1 = 0
\end{align*}
Since $\text{score} = 0$, the point lies exactly on the hyperplane, so it is a \textbf{support vector}.\\
\boxed{x=(1,1) \text{ lies on the decision boundary}}

\textbf{Reading the Score:}
\begin{enumerate}[leftmargin=2em,itemsep=4pt]
\item The sign of $w\cdot x+b$ gives the predicted class
\item The magnitude of $w\cdot x+b$ (before normalizing by $\|w\|$) hints at how far the point is from the boundary — larger magnitude means the model is more confident
\item Example 2.30 shows a point exactly on the hyperplane, which is precisely what defines a support vector
\end{enumerate}

\subsection{Computing the Margin}

An SVM has weight vector $w = (2,-1)$. Compute the margin width.

\textbf{Solution:}
\begin{align*}
\|w\| &= \sqrt{2^2+(-1)^2} = \sqrt{4+1} = \sqrt{5} \\
\text{Margin} &= \frac{2}{\sqrt{5}}
\end{align*}
\boxed{\text{Margin} \approx 0.894}

An SVM has weight vector $w = (3,4)$. Compute the margin width.

\textbf{Solution:}
\begin{align*}
\|w\| &= \sqrt{3^2+4^2} = \sqrt{9+16} = \sqrt{25} = 5 \\
\text{Margin} &= \frac{2}{5}
\end{align*}
\boxed{\text{Margin} = 0.4}

An SVM has $w = (1,1)$ and $b = -2$. Find the distance from the point $x=(4,4)$ to the hyperplane.

\textbf{Solution:}
\begin{align*}
w\cdot x + b &= (1)(4) + (1)(4) + (-2) = 6 \\
\|w\| &= \sqrt{1^2+1^2} = \sqrt{2} \\
d &= \frac{|6|}{\sqrt{2}}
\end{align*}
\boxed{d \approx 4.243}

