\subsection{The Logistic Regression Decision Rule}

\begin{enumerate}[leftmargin=2em,itemsep=4pt]
\item If $P(y=1\mid x) \ge 0.5$ predict class $1$ otherwise predict class $0$ \hfill\textit{(threshold rule)}
\item $P(y=1\mid x) \ge 0.5$ is equivalent to $\text{net}=w\cdot x+b \ge 0$ \hfill\textit{(shortcut check)}
\item The decision boundary is the hyperplane $w\cdot x+b=0$ \hfill\textit{(same linear boundary idea as SVM)}
\end{enumerate}

A model has $w=(0.8,-0.5)$, $b=-0.1$. Classify $x=(2,1)$. (Use $e^{-1}\approx0.3679$.)

\textbf{Solution:}
\begin{align*}
\text{net} &= (0.8)(2)+(-0.5)(1)+(-0.1) = 1.6-0.5-0.1 = 1.0 \\
P &= \frac{1}{1+e^{-1}} = \frac{1}{1+0.3679} = \frac{1}{1.3679}
\end{align*}
\[
P \approx 0.731
\]
Since $P \ge 0.5$:
\boxed{\text{Predicted class} = 1}

A model has $w=(0.3,0.3)$, $b=-1.5$. Classify $x=(1,1)$. (Use $e^{0.9}\approx2.4596$.)

\textbf{Solution:}
\begin{align*}
\text{net} &= (0.3)(1)+(0.3)(1)+(-1.5) = 0.3+0.3-1.5 = -0.9 \\
P &= \frac{1}{1+e^{0.9}} = \frac{1}{1+2.4596} = \frac{1}{3.4596}
\end{align*}
\[
P \approx 0.289
\]
Since $P < 0.5$:
\boxed{\text{Predicted class} = 0}

A model has $w=(1,-1)$, $b=0$. Classify $x=(2,2)$.

\textbf{Solution:}
\begin{align*}
\text{net} &= (1)(2)+(-1)(2)+0 = 2-2 = 0 \\
P &= \frac{1}{1+e^{0}} = \frac{1}{1+1} = 0.5
\end{align*}
Since $P = 0.5$ meets the threshold $\ge 0.5$:
\boxed{\text{Predicted class} = 1 \ (\text{point lies exactly on the decision boundary})}

